file.content:
  display: flex; align-items: flex-start; gap: 10px;
}
.accordion-steps li:last-child { border-bottom: none; }
.accordion-steps .step-num {
  width: 22px; height: 22px; border-radius: 50%; background: var(--accent-green-dim);
  color: var(--accent-green); display: flex; align-items: center; justify-content: center;
  font-size: 0.7rem; font-weight: 700; flex-shrink: 0; margin-top: 1px;
}
.accordion-code {
  margin-top: 12px; background: var(--code-bg); border: 1px solid var(--code-border);
  border-radius: var(--radius); padding: 14px 18px; font-family: var(--font-mono);
  font-size: 0.8rem; color: var(--accent-green); overflow-x: auto;
}

/* Launch CTA */
.launch-section { background: var(--bg-secondary); }
.launch-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px;
  max-width: 800px; margin: 0 auto;
}
.launch-card {
  background: var(--bg-primary); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 28px; transition: all 0.2s;
}
.launch-card:hover { border-color: var(--text-tertiary); transform: translateY(-1px); }
.launch-card h3 { font-size: 1.05rem; font-weight: 700; margin-bottom: 8px; }
.launch-card p { color: var(--text-secondary); font-size: 0.88rem; margin-bottom: 16px; }

/* Community */
.community-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
  max-width: 900px; margin: 0 auto;
}
.community-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px; transition: all 0.2s;
  text-decoration: none; color: var(--text-primary); display: block;
}
.community-card:hover { border-color: var(--accent-cyan); background: var(--bg-tertiary); }
.community-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; display: flex; align-items: center; justify-content: space-between; }
.community-card h4 .arrow { color: var(--text-tertiary); font-size: 0.8rem; transition: transform 0.15s, color 0.15s; }
.community-card:hover h4 .arrow { transform: translateX(3px); color: var(--accent-cyan); }
.community-card p { font-size: 0.8rem; color: var(--text-secondary); }

/* Footer */
.site-footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 56px 24px 32px;
}
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px; max-width: 1000px; margin: 0 auto 40px; }
.footer-col h4 { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-primary); margin-bottom: 16px; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { color: var(--text-secondary); font-size: 0.85rem; }
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: 1000px; margin: 0 auto; padding-top: 24px;
  border-top: 1px solid var(--border); text-align: center;
  color: var(--text-tertiary); font-size: 0.8rem;
}

/* --- Interior Pages (with sidebar) --- */
.page-with-sidebar {
  display: flex; max-width: 1280px; margin: 0 auto; min-height: calc(100vh - var(--topnav-height) - 300px);
}
.sidebar {
  width: var(--sidebar-width); flex-shrink: 0;
  border-right: 1px solid var(--border); padding: 32px 20px;
  position: sticky; top: var(--topnav-height); height: calc(100vh - var(--topnav-height));
  overflow-y: auto; background: var(--bg-primary);
  transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
}
.sidebar.collapsed { width: 0; padding: 32px 0; opacity: 0; overflow: hidden; border-right: none; }
.sidebar-toggle {
  display: flex; align-items: center; gap: 6px; background: var(--bg-tertiary);
  border: 1px solid var(--border); color: var(--text-secondary); padding: 6px 12px;
  border-radius: 6px; cursor: pointer; font-family: var(--font-sans); font-size: 0.8rem;
  margin-bottom: 20px; transition: all 0.15s;
}
.sidebar-toggle:hover { color: var(--text-primary); border-color: var(--text-tertiary); }
.sidebar-nav { list-style: none; }
.sidebar-nav li { margin-bottom: 2px; }
.sidebar-nav a {
  display: block; padding: 7px 12px; border-radius: 6px; color: var(--text-secondary);
  font-size: 0.85rem; transition: all 0.12s;
}
.sidebar-nav a:hover, .sidebar-nav a.active { background: var(--bg-tertiary); color: var(--text-primary); }
.main-content {
  flex: 1; min-width: 0; padding: 48px 48px 80px;
}
.main-content .hero { text-align: left; padding: 0 0 40px; max-width: none; }
.main-content .hero h1 { font-size: 2.4rem; }
.main-content .hero p { max-width: none; margin: 0 0 24px; }

/* Cards Grid (generic) */
.cards-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.cards-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.info-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 24px; transition: all 0.2s;
}
.info-card:hover { border-color: var(--text-tertiary); }
.info-card .card-icon-sm {
  width: 36px; height: 36px; border-radius: 8px; display: flex;
  align-items: center; justify-content: center; font-size: 1.1rem;
  margin-bottom: 14px; background: var(--accent-green-dim); color: var(--accent-green);
}
.info-card:nth-child(2n) .card-icon-sm { background: var(--accent-cyan-dim); color: var(--accent-cyan); }
.info-card:nth-child(3n) .card-icon-sm { background: var(--accent-blue-dim); color: #8899c4; }
.info-card h4 { font-size: 0.95rem; font-weight: 700; margin-bottom: 6px; }
.info-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.55; }

/* Protocol Actor Cards */
.actor-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.actor-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 24px; text-align: center; transition: all 0.2s;
}
.actor-card:hover { border-color: var(--text-tertiary); }
.actor-card .actor-icon {
  width: 48px; height: 48px; border-radius: 50%; background: var(--accent-cyan-dim);
  color: var(--accent-cyan); display: flex; align-items: center; justify-content: center;
  margin: 0 auto 12px; font-size: 1.2rem; font-weight: 700;
}
.actor-card h4 { font-size: 0.9rem; font-weight: 600; margin-bottom: 4px; }
.actor-card p { color: var(--text-secondary); font-size: 0.8rem; }

/* Hero for interior pages - no gradient text */
.hero-plain h1 { background: none; -webkit-text-fill-color: var(--text-primary); color: var(--text-primary); }

/* Sub-sections */
.sub-section { margin-bottom: 48px; }
.sub-section h3 {
  font-size: 1.3rem; font-weight: 700; margin-bottom: 8px; padding-bottom: 12px;
  border-bottom: 1px solid var(--border-subtle);
}
.sub-section > p { color: var(--text-secondary); margin-bottom: 24px; font-size: 0.95rem; }

/* Status badge */
.status-badge {
  display: inline-block; font-size: 0.72rem; font-weight: 600; padding: 3px 10px;
  border-radius: 12px; background: var(--accent-cyan-dim); color: var(--accent-cyan);
  margin-left: 8px; vertical-align: middle;
}

/* Support */
.support-category-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
}
.support-cat-card {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px; transition: all 0.2s;
}
.support-cat-card:hover { border-color: var(--accent-cyan); }
.support-cat-card h4 { font-size: 0.9rem; font-weight: 600; margin-bottom: 4px; }
.support-cat-card p { color: var(--text-secondary); font-size: 0.8rem; }

/* Contact section */
.contact-section {
  text-align: center; padding: 48px 24px; max-width: 600px; margin: 0 auto;
}
.contact-section h3 { font-size: 1.4rem; margin-bottom: 12px; }
.contact-section p { color: var(--text-secondary); margin-bottom: 20px; }

/* Responsive */
@media (max-width: 1024px) {
  .cards-grid { grid-template-columns: repeat(2, 1fr); }
  .actor-grid { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .support-category-grid { grid-template-columns: repeat(2, 1fr); }
  .main-content { padding: 32px 32px 60px; }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .product-cards { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .cards-grid, .cards-grid-2 { grid-template-columns: 1fr; }
  .actor-grid { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .support-category-grid { grid-template-columns: 1fr; }

  .topnav-links { display: none; }
  .topnav-links.open {
    display: flex; flex-direction: column; position: fixed; top: var(--topnav-height);
    left: 0; right: 0; background: var(--bg-primary); border-bottom: 1px solid var(--border);
    padding: 16px 24px; gap: 12px; z-index: 99;
  }
  .mobile-menu-btn { display: block; }

  .page-with-sidebar { flex-direction: column; }
  .sidebar {
    width: 100%; height: auto; position: static; border-right: none;
    border-bottom: 1px solid var(--border); padding: 20px;
  }
  .sidebar.collapsed { width: 100%; padding: 12px 20px; opacity: 1; border-bottom: 1px solid var(--border); }
  .sidebar.collapsed .sidebar-nav { display: none; }
  .main-content { padding: 24px 20px; }
  .main-content .hero h1 { font-size: 1.7rem; }
}

@media (max-width: 480px) {
  .topnav-inner { padding: 0 12px; gap: 12px; }
  .topnav-ask { display: none; }
  .hero { padding: 48px 16px 40px; }
  .hero h1 { font-size: 1.6rem; }
  .section { padding: 40px 16px; }
}

