291	  background: var(--bg-primary); border: 1px solid var(--border);
292	  border-radius: var(--radius-lg); padding: 28px; transition: all 0.2s;
293	}
294	.launch-card:hover { border-color: var(--text-tertiary); transform: translateY(-1px); }
295	.launch-card h3 { font-size: 1.05rem; font-weight: 700; margin-bottom: 8px; }
296	.launch-card p { color: var(--text-secondary); font-size: 0.88rem; margin-bottom: 16px; }
297	
298	/* Community */
299	.community-grid {
300	  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
301	  max-width: 900px; margin: 0 auto;
302	}
303	.community-card {
304	  background: var(--bg-secondary); border: 1px solid var(--border);
305	  border-radius: var(--radius); padding: 20px; transition: all 0.2s;
306	  text-decoration: none; color: var(--text-primary); display: block;
307	}
308	.community-card:hover { border-color: var(--accent-cyan); background: var(--bg-tertiary); }
309	.community-card h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; display: flex; align-items: center; justify-content: space-between; }
310	.community-card h4 .arrow { color: var(--text-tertiary); font-size: 0.8rem; transition: transform 0.15s, color 0.15s; }
311	.community-card:hover h4 .arrow { transform: translateX(3px); color: var(--accent-cyan); }
312	.community-card p { font-size: 0.8rem; color: var(--text-secondary); }
313	
314	/* Footer */
315	.site-footer {
316	  background: var(--bg-secondary); border-top: 1px solid var(--border);
317	  padding: 56px 24px 32px;
318	}
319	.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px; max-width: 1000px; margin: 0 auto 40px; }
320	.footer-col h4 { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-primary); margin-bottom: 16px; }
321	.footer-col ul { list-style: none; }
322	.footer-col li { margin-bottom: 10px; }
323	.footer-col a { color: var(--text-secondary); font-size: 0.85rem; }
324	.footer-col a:hover { color: var(--text-primary); }
325	.footer-bottom {
326	  max-width: 1000px; margin: 0 auto; padding-top: 24px;
327	  border-top: 1px solid var(--border); text-align: center;
328	  color: var(--text-tertiary); font-size: 0.8rem;
329	}
330	
331	/* --- Interior Pages (with sidebar) --- */
332	.page-with-sidebar {
333	  display: flex; max-width: 1280px; margin: 0 auto; min-height: calc(100vh - var(--topnav-height) - 300px);
334	}
335	.sidebar {
336	  width: var(--sidebar-width); flex-shrink: 0;
337	  border-right: 1px solid var(--border); padding: 32px 20px;
338	  position: sticky; top: var(--topnav-height); height: calc(100vh - var(--topnav-height));
339	  overflow-y: auto; background: var(--bg-primary);
340	  transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
341	}
342	.sidebar.collapsed { width: 0; padding: 32px 0; opacity: 0; overflow: hidden; border-right: none; }
343	.sidebar-toggle {
344	  display: flex; align-items: center; gap: 6px; background: var(--bg-tertiary);
345	  border: 1px solid var(--border); color: var(--text-secondary); padding: 6px 12px;
346	  border-radius: 6px; cursor: pointer; font-family: var(--font-sans); font-size: 0.8rem;
347	  margin-bottom: 20px; transition: all 0.15s;
348	}
349	.sidebar-toggle:hover { color: var(--text-primary); border-color: var(--text-tertiary); }
350	.sidebar-nav { list-style: none; }
351	.sidebar-nav li { margin-bottom: 2px; }
352	.sidebar-nav a {
353	  display: block; padding: 7px 12px; border-radius: 6px; color: var(--text-secondary);
354	  font-size: 0.85rem; transition: all 0.12s;
355	}
356	.sidebar-nav a:hover, .sidebar-nav a.active { background: var(--bg-tertiary); color: var(--text-primary); }
357	.main-content {
358	  flex: 1; min-width: 0; padding: 48px 48px 80px;
359	}
360	.main-content .hero { text-align: left; padding: 0 0 40px; max-width: none; }
361	.main-content .hero h1 { font-size: 2.4rem; }
362	.main-content .hero p { max-width: none; margin: 0 0 24px; }
363	
364	/* Cards Grid (generic) */
365	.cards-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
366	.cards-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
367	.info-card {
368	  background: var(--bg-secondary); border: 1px solid var(--border);
369	  border-radius: var(--radius); padding: 24px; transition: all 0.2s;
370	}
371	.info-card:hover { border-color: var(--text-tertiary); }
372	.info-card .card-icon-sm {
373	  width: 36px; height: 36px; border-radius: 8px; display: flex;
374	  align-items: center; justify-content: center; font-size: 1.1rem;
375	  margin-bottom: 14px; background: var(--accent-green-dim); color: var(--accent-green);
376	}
377	.info-card:nth-child(2n) .card-icon-sm { background: var(--accent-cyan-dim); color: var(--accent-cyan); }
378	.info-card:nth-child(3n) .card-icon-sm { background: var(--accent-blue-dim); color: #8899c4; }
379	.info-card h4 { font-size: 0.95rem; font-weight: 700; margin-bottom: 6px; }
380	.info-card p { color: var(--text-secondary); font-size: 0.85rem; line-height: 1.55; }
381	
382	/* Protocol Actor Cards */
383	.actor-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
384	.actor-card {
385	  background: var(--bg-secondary); border: 1px solid var(--border);
386	  border-radius: var(--radius); padding: 24px; text-align: center; transition: all 0.2s;
387	}
388	.actor-card:hover { border-color: var(--text-tertiary); }
389	.actor-card .actor-icon {
390	  width: 48px; height: 48px; border-radius: 50%; background: var(--accent-cyan-dim);
391	  color: var(--accent-cyan); display: flex; align-items: center; justify-content: center;
392	  margin: 0 auto 12px; font-size: 1.2rem; font-weight: 700;
393	}
394	.actor-card h4 { font-size: 0.9rem; font-weight: 600; margin-bottom: 4px; }
395	.actor-card p { color: var(--text-secondary); font-size: 0.8rem; }
396	
397	/* Hero for interior pages - no gradient text */
398	.hero-plain h1 { background: none; -webkit-text-fill-color: var(--text-primary); color: var(--text-primary); }
399	
400	/* Sub-sections */
401	.sub-section { margin-bottom: 48px; }
402	.sub-section h3 {
403	  font-size: 1.3rem; font-weight: 700; margin-bottom: 8px; padding-bottom: 12px;
404	  border-bottom: 1px solid var(--border-subtle);
405	}
406	.sub-section > p { color: var(--text-secondary); margin-bottom: 24px; font-size: 0.95rem; }
407	
408	/* Status badge */
409	.status-badge {
410	  display: inline-block; font-size: 0.72rem; font-weight: 600; padding: 3px 10px;
411	  border-radius: 12px; background: var(--accent-cyan-dim); color: var(--accent-cyan);
412	  margin-left: 8px; vertical-align: middle;
413	}
414	
415	/* Support */
416	.support-category-grid {
417	  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
418	}
419	.support-cat-card {
420	  background: var(--bg-secondary); border: 1px solid var(--border);
421	  border-radius: var(--radius); padding: 20px; transition: all 0.2s;
422	}
423	.support-cat-card:hover { border-color: var(--accent-cyan); }
424	.support-cat-card h4 { font-size: 0.9rem; font-weight: 600; margin-bottom: 4px; }
425	.support-cat-card p { color: var(--text-secondary); font-size: 0.8rem; }
426	
427	/* Contact section */
428	.contact-section {
429	  text-align: center; padding: 48px 24px; max-width: 600px; margin: 0 auto;
430	}
431	.contact-section h3 { font-size: 1.4rem; margin-bottom: 12px; }
432	.contact-section p { color: var(--text-secondary); margin-bottom: 20px; }
433	
434	/* Responsive */
435	@media (max-width: 1024px) {
436	  .cards-grid { grid-template-columns: repeat(2, 1fr); }
437	  .actor-grid { grid-template-columns: repeat(2, 1fr); }
438	  .community-grid { grid-template-columns: repeat(2, 1fr); }
439	  .support-category-grid { grid-template-columns: repeat(2, 1fr); }
440	  .main-content { padding: 32px 32px 60px; }
441	}
442	
443	@media (max-width: 768px) {
444	  .hero h1 { font-size: 2rem; }
445	  .hero p { font-size: 1rem; }
446	  .product-cards { grid-template-columns: 1fr; }
447	  .launch-grid { grid-template-columns: 1fr; }
448	  .cards-grid, .cards-grid-2 { grid-template-columns: 1fr; }
449	  .actor-grid { grid-template-columns: repeat(2, 1fr); }
450	  .community-grid { grid-template-columns: 1fr; }
451	  .footer-grid { grid-template-columns: repeat(2, 1fr); }
452	  .support-category-grid { grid-template-columns: 1fr; }
453	
454	  .topnav-links { display: none; }
455	  .topnav-links.open {
456	    display: flex; flex-direction: column; position: fixed; top: var(--topnav-height);
457	    left: 0; right: 0; background: var(--bg-primary); border-bottom: 1px solid var(--border);
458	    padding: 16px 24px; gap: 12px; z-index: 99;
459	  }
460	  .mobile-menu-btn { display: block; }
461	
462	  .page-with-sidebar { flex-direction: column; }
463	  .sidebar {
464	    width: 100%; height: auto; position: static; border-right: none;
465	    border-bottom: 1px solid var(--border); padding: 20px;
466	  }
467	  .sidebar.collapsed { width: 100%; padding: 12px 20px; opacity: 1; border-bottom: 1px solid var(--border); }
468	  .sidebar.collapsed .sidebar-nav { display: none; }
469	  .main-content { padding: 24px 20px; }
470	  .main-content .hero h1 { font-size: 1.7rem; }
471	}
472	
